<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {hostBytes} from './hostBilling'
const props=defineProps<{user:Record<string,any>,api:(p:string,m?:string,b?:any)=>Promise<any>}>(),emit=defineEmits<{close:[],changed:[]}>()
const rows=ref<Record<string,any>[]>([]),nodes=ref<Record<string,any>[]>([]),clients=ref<Record<string,any>[]>([]),draft=ref<Record<string,any>|null>(null),busy=ref(false),error=ref(''),notice=ref(''),link=ref('')
let alive=true,timer:ReturnType<typeof setTimeout>
const base='proxy-users/'+props.user.id+'/devices'
async function load(){const [d,c,n]=await Promise.all([props.api(base),props.api('client-catalog'),props.api('client-policies/nodes?user_id='+props.user.id)]);if(alive){rows.value=d;clients.value=c;nodes.value=n.filter((v:Record<string,any>,i:number,a:Record<string,any>[])=>!['shadowsocks','snell'].includes(v.kind)&&a.findIndex(x=>x.id===v.id)===i)}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();await load();emit('changed')}catch(e){error.value=String(e)}finally{busy.value=false}}
function save(){const d=draft.value;if(!d)return;void run(async()=>{const r=await props.api(base+(d.id?'/'+d.id:''),d.id?'PUT':'POST',{name:d.name,client_id:d.client_id,enabled:!!d.enabled,version:d.version,all_nodes:d.all_nodes??true,service_ids:d.service_ids??[]});draft.value=null;if(r.url)link.value=r.url;notice.value='设备身份已保存，在线 Agent 将同步独立凭据。'})}
function toggle(d:Record<string,any>){void run(async()=>{await props.api(base+'/'+d.id,'PUT',{name:d.name,client_id:d.client_id,enabled:!d.enabled,version:d.version});link.value='';notice.value=d.enabled?'设备已停用，凭据撤销等待 Agent 同步。':'设备已启用。'})}
function remove(d:Record<string,any>){if(!window.confirm('删除设备 '+d.name+' 及其专属订阅，并撤销此设备凭据？'))return;void run(async()=>{await props.api(base+'/'+d.id,'DELETE');link.value='';notice.value='设备及专属订阅已删除；用户其他设备不受影响。'})}
function share(d:Record<string,any>){void run(async()=>{link.value=(await props.api(base+'/'+d.id+'/link')).url})}
async function copy(){try{await navigator.clipboard.writeText(link.value);notice.value='设备订阅已复制'}catch{notice.value='请手动复制下方链接'}}
function schedule(){timer=setTimeout(async()=>{if(document.visibilityState!=='hidden'&&!busy.value)try{await load()}catch{};if(alive)schedule()},30000)}
onMounted(()=>{void run(async()=>{});schedule()});onUnmounted(()=>{alive=false;clearTimeout(timer);link.value=''})
</script>
<template><div class="modal-backdrop"><section class="modal devices-modal" role="dialog" aria-modal="true" aria-label="用户设备管理"><div class="modal-heading"><div><h2>{{user.name}} · 设备与客户端</h2><p class="muted">启用 {{rows.filter(d=>d.enabled).length}} / {{user.effective_max_devices||'未启用限制'}} · 用户与所属组取最严格的非零设备上限</p></div><button class="secondary" @click="emit('close')">关闭</button></div><div class="form-content"><p class="form-note">每台设备使用独立订阅与连接凭据，可单独停用。客户端信息来自订阅请求头 / 手动名称，来源 IP 来自代理连接元数据。标准 VLESS/Trojan 等协议不可靠地回传物理设备 ID；同一凭据被复制时无法区分物理设备。开启设备上限会撤销通用用户身份，需导入设备专属链接。SS/Snell 共享密钥不提供独立设备限制。</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><button class="primary" :disabled="busy" @click="draft={name:'',client_id:'mihomo',enabled:true,version:0,all_nodes:true,service_ids:[]}">＋ 登记设备 / 生成专属订阅</button><form v-if="draft" class="device-editor" @submit.prevent="save"><div class="fields"><label>设备名称<input v-model="draft.name" required maxlength="100" placeholder="我的手机 / 笔记本"></label><label>客户端格式<select v-model="draft.client_id"><option v-for="c in clients" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div><label class="check-label"><input v-model="draft.all_nodes" type="checkbox">继承用户组的全部授权入站</label><div v-if="!draft.all_nodes" class="choice-list"><label v-for="n in nodes" :key="n.id"><input v-model="draft.service_ids" type="checkbox" :value="n.id">{{n.node_name??n.name}} · {{n.kind}}</label><p class="muted">未选择任何入站时此设备没有连接权限；不会回退为全部。</p></div><div class="row-actions"><button class="primary" :disabled="busy">保存设备</button><button type="button" class="secondary" @click="draft=null">取消</button></div></form><div v-if="link" class="device-link"><label>设备专属订阅（包含访问凭据）<input :value="link" readonly aria-label="设备专属订阅"></label><button class="secondary" @click="copy">复制链接</button></div><div class="device-grid"><article v-for="d in rows" :key="d.id"><div class="device-title"><h3>{{d.name}}</h3><span :class="['status',d.enabled?'succeeded':'pending']">{{d.enabled?'启用':'停用'}}</span></div><p>{{clients.find(c=>c.id===d.client_id)?.name??d.client_id}}</p><dl><dt>节点权限</dt><dd>{{d.all_nodes?'跟随用户全部授权':(d.service_ids?.length??0)+' 个指定入站'}}</dd><dt>客户端自报</dt><dd>{{d.user_agent||'尚未请求订阅 / 未上报'}}</dd><dt>最近代理活动</dt><dd>{{d.last_connected_at?new Date(d.last_connected_at).toLocaleString():'尚未观察到'}}</dd><dt>最近来源 IP</dt><dd>{{d.source_ip||'—'}}</dd><dt>原始累计</dt><dd>{{hostBytes(d.raw_lifetime_bytes)}}</dd></dl><div class="row-actions"><button class="text-button" :disabled="busy||!d.enabled" @click="share(d)">分享订阅</button><button class="text-button" :disabled="busy" @click="draft={...d}">编辑</button><button class="text-button" :disabled="busy" @click="toggle(d)">{{d.enabled?'停用':'启用'}}</button><button class="text-button danger" :disabled="busy" @click="remove(d)">删除</button></div></article></div><p v-if="!rows.length" class="console-empty">尚未登记设备。先为用户授权支持独立身份的入站，再创建设备。</p></div></section></div></template>
<style scoped>.devices-modal{width:min(1100px,96vw)}.device-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:18px}.device-grid article,.device-editor,.device-link{padding:16px;border:1px solid var(--border);border-radius:12px;min-width:0}.device-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.device-title h3{margin:0;font-size:17px}.device-grid p{font-size:12px;color:var(--muted)}.device-grid dl{font-size:12px;line-height:1.7}.device-grid dt{color:var(--muted);margin-top:8px}.device-grid dd{margin:0;overflow-wrap:anywhere}.device-editor,.device-link{margin-top:16px}.device-link input{width:100%;min-width:0}.device-link button{margin-top:10px}@media(max-width:680px){.device-grid{grid-template-columns:1fr}}</style>
